using ProductHash128 = TestFx.Hashing.XxHash128;

namespace Microsoft.Testing.Extensions.UnitTests;

[TestClass]
public sealed class TrxHashingBehaviorTests
{
    // Independent vectors verified with the already-cached official System.IO.Hashing 10.0.12,
    // not generated by the adapted product implementation during test execution.
    [TestMethod]
    [DataRow(241, 0L, "06229596E1DE710AED93572E52ACAC83", DisplayName = "Long hash default seed")]
    [DataRow(241, 1L, "C764D01397CDF3D3BAA643BCADC71A73", DisplayName = "Long hash positive seed")]
    [DataRow(256, -1L, "90C48E1508A7742A7E34D2217DB596EE", DisplayName = "Long hash negative seed")]
    [DataRow(1024, 1L, "830C4A3AD6B206AF9C82B3EFE3F1992C", DisplayName = "Block hash positive seed")]
    [DataRow(1024, 1234605616436508552L, "7DF3C027E882D13A2C276266BBEF67BF", DisplayName = "Block hash full-width seed")]
    public void Hash_SeededLongInputsMatchIndependentReferenceAndPreserveBuffers(int length, long seed, string expectedHex)
    {
        byte[] source = CreateInput(length);
        byte[] original = (byte[])source.Clone();
        byte[] expected = ParseHex(expectedHex);

        byte[] allocated = ProductHash128.Hash(source, seed);
        byte[] destination = Enumerable.Repeat((byte)0xA5, 24).ToArray();
        bool success = ProductHash128.TryHash(source, destination, out int written, seed);

        Assert.AreSequenceEqual(expected, allocated);
        Assert.IsTrue(success);
        Assert.AreEqual(16, written);
        Assert.AreSequenceEqual(expected, destination.Take(16));
        Assert.AreSequenceEqual(Enumerable.Repeat((byte)0xA5, 8), destination.Skip(16));
        Assert.AreSequenceEqual(original, source);
    }

    [TestMethod]
    [DataRow(0)]
    [DataRow(15)]
    public void TryHash_ShortDestinationWritesNothingAndHashReportsExactParameter(int length)
    {
        byte[] source = CreateInput(241);
        byte[] destination = Enumerable.Repeat((byte)0xA5, length).ToArray();
        byte[] original = (byte[])destination.Clone();

        bool success = ProductHash128.TryHash(source, destination, out int written, 1);
        ArgumentException error = Assert.ThrowsExactly<ArgumentException>(() => ProductHash128.Hash(source, destination, 1));

        Assert.IsFalse(success);
        Assert.AreEqual(0, written);
        Assert.AreSequenceEqual(original, destination);
        Assert.AreEqual("destination", error.ParamName);
        Assert.StartsWith("Destination is too short", error.Message);
    }

    [TestMethod]
    public void Hash_NullSourceReportsExactParameter()
    {
        ArgumentNullException error = Assert.ThrowsExactly<ArgumentNullException>(() => ProductHash128.Hash(null!, 1));

        Assert.AreEqual("source", error.ParamName);
    }

    [TestMethod]
    [DataRow(0L, "C9B63FA28A4FA083B6D0A639BD770002", DisplayName = "Streaming multi-block default seed")]
    [DataRow(1L, "B8426FE5C52FE94AAFF24B24399F219F", DisplayName = "Streaming multi-block positive seed")]
    [DataRow(-1L, "A38E5DB03E7FDCB8E920FBDE236BCF15", DisplayName = "Streaming multi-block negative seed")]
    public void StreamingHash_MultiBlockPartitionsAndResetRetainIndependentSeededVector(long seed, string expectedHex)
    {
        byte[] source = CreateInput(2049);
        byte[] original = (byte[])source.Clone();
        byte[] expected = ParseHex(expectedHex);
        var hash = new ProductHash128(seed);

        hash.Append(source);

        Assert.AreSequenceEqual(expected, ProductHash128.Hash(source, seed));
        Assert.AreSequenceEqual(expected, hash.GetCurrentHash());
        hash.Append([]);
        Assert.AreSequenceEqual(expected, hash.GetCurrentHash());
        hash.Reset();
        int offset = 0;
        foreach (int length in new[] { 17, 1, 63, 255, 1024, 689 })
        {
            hash.Append(source.Skip(offset).Take(length).ToArray());
            offset += length;
        }

        Assert.AreEqual(source.Length, offset);
        Assert.AreSequenceEqual(expected, hash.GetCurrentHash());
        Assert.AreSequenceEqual(original, source);
    }

    private static byte[] CreateInput(int length)
        => [.. Enumerable.Range(0, length).Select(index => unchecked((byte)((index * 131) + 17)))];

    private static byte[] ParseHex(string hex)
        => [.. Enumerable.Range(0, hex.Length / 2).Select(index => byte.Parse(hex.Substring(index * 2, 2), NumberStyles.HexNumber, CultureInfo.InvariantCulture))];
}
